SELECT FROM api_interface LEFT JOIN data_source ds ON ds.id = api_interface.data_source_id
AND api_interface.data_source_id = #{dataSourceId}
AND (api_interface.english_name LIKE CONCAT('%', #{name}, '%') OR api_interface.chinese_name LIKE CONCAT('%', #{name}, '%'))
AND api_interface.status = #{status}
ORDER BY api_interface.created_at DESC

