english_name = #{englishName}, chinese_name = #{chineseName}, url_slug = #{urlSlug}, method = #{method}, data_source_id = #{dataSourceId}, query_type = #{queryType}, query_content = #{queryContent}, is_paginated = #{isPaginated}, page_size = #{pageSize}, status = #{status}, updated_at = #{updatedAt}, last_modified_by = #{lastModifiedBy},
WHERE id = #{id}

